<?php
namespace App\Models; use Illuminate\Database\Eloquent\Concerns\HasUuids; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\HasMany;
final class Bordereau extends Model { use HasUuids; protected $fillable=['tenant_id','carrier_id','type','bordereau_number','period_start','period_end','status','item_count','gross_premium_minor','commission_minor','currency','prepared_by','submitted_by','submitted_at','carrier_reference','content_hash','idempotency_key','approved_by','approved_at','acknowledged_at','rejection_reason']; protected function casts():array{return['period_start'=>'date','period_end'=>'date','submitted_at'=>'datetime','approved_at'=>'datetime','acknowledged_at'=>'datetime'];} public function items():HasMany{return$this->hasMany(BordereauItem::class);} }
